199:   const consider = (obj, point, type) => {
200:     const dx = point.x - p.x, dz = point.z - p.z;
201:     const dist = Math.hypot(dx, dz);
202:     if (dist > maxDist) return;
203:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
204:     if (dot < -0.25) return;
205:     const score = dist + (dot < 0.15 ? 0.55 : 0);
206:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
207:   };
208:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
209:   for (const weapon of weapons) if (weapon.state === 'ground') consider(weapon, weapon.group.position, 'weapon');
210:   return best;
211: }
