453:       (keys.has('KeyD') || keys.has('ArrowRight') ? 1 : 0) - (keys.has('KeyA') || keys.has('ArrowLeft') ? 1 : 0),
454:       (keys.has('KeyW') || keys.has('ArrowUp') ? 1 : 0) - (keys.has('KeyS') || keys.has('ArrowDown') ? 1 : 0)
455:     );
456:     const input = moveInput.clone().add(keyboard);
457:     if (input.length() > 1) input.normalize();
458:     const forward = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw));
459:     const right = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));
460:     player.group.position.addScaledVector(forward, input.y * player.speed * dt);
461:     player.group.position.addScaledVector(right, input.x * player.speed * dt);
462:     player.group.position.x = THREE.MathUtils.clamp(player.group.position.x, -1.76, 1.76);
463:     player.group.position.z = THREE.MathUtils.clamp(player.group.position.z, -1.76, 1.76);
464:   }
