466:   if (heldNPC && player.alive) heldNPC.setGrabbed(player);
467:   for (const npc of npcs) npc.update(dt, game);
468:   for (const weapon of weapons) weapon.update(dt, time, game);
469:   fx.update(dt, time);
470: 
471:   const targetArm = swingT > 0 ? -1.25 * (swingT / 0.24) : 0;
472:   armR.rotation.x += (targetArm - armR.rotation.x) * Math.min(1, dt * 18);
473:   armL.rotation.x += ((heldNPC ? -0.5 : 0) - armL.rotation.x) * Math.min(1, dt * 10);
474:   if (viewWeapon) viewWeapon.rotation.x = -0.2 + (swingT > 0 ? -0.7 * (swingT / 0.24) : 0);
475: 
476:   if (shakeT > 0) {
